// Normalize MR (with commits) — open/update path only
// Input: Get MR Commits HTTP response (top-level JSON array of commit objects)
// MR metadata: from original webhook payload via $('MR Action?')
const mrPayload = $('MR Action?').first().json;
const attrs = mrPayload.object_attributes || {};
const action = attrs.action;
const mrIid = attrs.iid;
const mrUrl = attrs.url || '';
const mrTitle = attrs.title || '';
const sourceBranch = attrs.source_branch || '';
const targetBranch = attrs.target_branch || '';
const description = attrs.description || '';
const items = [];

if (action === 'open' || action === 'update') {
  // Classify MR description (e.g. "closes DEV-15" in the description body)
  const descRefs = classifyMessage(description);
  // Classify each fetched commit's message
  // HTTP Request v4.2 does not auto-split top-level JSON arrays — the response
  // arrives as one item whose .json is the array. Handle both shapes defensively.
  const inputAll = $input.all();
  const commitsRaw = (inputAll.length === 1 && Array.isArray(inputAll[0].json))
    ? inputAll[0].json
    : inputAll.map(i => i.json);
  const commitRefs = [];
  for (const c of commitsRaw) {
    const msg = c.message || c.title || '';
    const refs = classifyMessage(msg);
    for (const r of refs) commitRefs.push(r);
  }
  // Merge and dedup by issueKey+action
  const allRefs = descRefs.concat(commitRefs);
  const seen = new Set();
  for (const r of allRefs) {
    if (seen.has(r.issueKey + r.action)) continue;
    seen.add(r.issueKey + r.action);
    const act = r.action === 'close' ? 'close-in-mr' : (r.action === 'reopen' ? 'reopen' : 'mr-open');
    items.push({
      json: {
        issueKey: r.issueKey, action: act, mrIid: mrIid, mrUrl: mrUrl,
        mrTitle: mrTitle, sourceBranch: sourceBranch, targetBranch: targetBranch,
        mrDescription: description, gitlabProjectId: String((mrPayload.project && mrPayload.project.id) || ''),
        source: 'mr', planeProjectUuid: PLANE_PROJECT.uuid,
      },
    });
  }
}
return items;

