    if (!seen.has(key + ':close') && !seen.has(key + ':reopen') && !seen.has(key + ':mention')) {
      results.push({issueKey: key, action: 'mention'}); seen.add(key + ':mention');
    }
  }
  return results;
}

// Post-fetch guard: re-evaluate shouldChangeState using current Plane state
const wi = $input.first().json;
const reducerItems = $('Reducer').all();
const idx = $itemIndex || 0;
const r = reducerItems[idx] ? reducerItems[idx].json : {};

const projStates = PLANE_PROJECT.states;
const stateNameByUuid = {};
for (const k of Object.keys(projStates)) stateNameByUuid[projStates[k]] = k;

const currentStateName = stateNameByUuid[wi.state] || 'unknown';
const targetStateName = stateNameByUuid[r.targetStateUuid] || 'unknown';
const actionLabel = r.desiredStateName || '';

let shouldChangeState = r.shouldChangeState;
let guardReason = r.guardReason || '';

if (currentStateName === 'cancelled') {
  shouldChangeState = false; guardReason = 'protected: Cancelled is human-owned';
} else if (currentStateName === 'done' && actionLabel !== 'reopen') {
  shouldChangeState = false; guardReason = 'protected: Done cannot be downgraded except by reopen';
} else if (currentStateName === 'inReview' && (actionLabel === 'mention' || actionLabel === 'mr-open')) {
  shouldChangeState = false; guardReason = 'protected: In Review not downgraded by bare mention';
} else if (wi.state === r.targetStateUuid) {
  shouldChangeState = false; guardReason = 'already in target state';
} else if (actionLabel === 'mr-closed' && currentStateName !== 'inProgress' && currentStateName !== 'inReview') {
  shouldChangeState = false; guardReason = 'mr-closed: can only downgrade from In Progress/In Review';
}

return [{
  json: {
    issueKey: r.issueKey,
    workItemId: wi.id,
    project: wi.project,
    currentState: wi.state,
    currentStateName: currentStateName,
    targetStateUuid: r.targetStateUuid,
    targetStateName: targetStateName,
    shouldChangeState: shouldChangeState,
    guardReason: guardReason,
    commentHtml: r.commentHtml,
    externalId: r.externalId,
    externalSource: r.externalSource,
    mrUrl: r.mrUrl || '',
    mrTitle: r.mrTitle || '',
    gitlabProjectId: r.gitlabProjectId || '',
    commitShas: r.commitShas || [],
    mrIid: r.mrIid || '',
    mrDescription: r.mrDescription || '',
    workItemUrl: `https://plane.nforensic.site/${WORKSPACE_SLUG}/projects/${wi.project}/work-items/${wi.id}`,
  },
}];

// Group Apply Guards output by commit SHA / MR IID, build GitLab link-back payloads
const allItems = $input.all().map(i => i.json);
const commits = {};  // sha -> { gitlabProjectId, issues: [{key, url}] }
const mrs = {};      // mrIid -> { gitlabProjectId, description, issues: [{key, url}] }

for (const item of allItems) {
  const url = item.workItemUrl || '';
  const key = item.issueKey || '';
  // Commits
  if (item.commitShas && item.commitShas.length > 0) {
    for (const sha of item.commitShas) {
      if (!commits[sha]) commits[sha] = { gitlabProjectId: item.gitlabProjectId, issues: [] };
      if (!commits[sha].issues.find(i => i.key === key)) commits[sha].issues.push({ key, url });
    }
  }
  // MRs
  if (item.mrIid && item.mrDescription) {
    if (!mrs[item.mrIid]) mrs[item.mrIid] = { gitlabProjectId: item.gitlabProjectId, description: item.mrDescription, issues: [] };
    if (!mrs[item.mrIid].issues.find(i => i.key === key)) mrs[item.mrIid].issues.push({ key, url });
  }
}

const results = [];
// Commit comment payloads
for (const sha of Object.keys(commits)) {
  const c = commits[sha];
  if (!c.gitlabProjectId) continue;
  const note = c.issues.map(i => `[${i.key}](${i.url})`).join(' · ');
  results.push({ json: { linkType: 'commit', gitlabProjectId: c.gitlabProjectId, commitSha: sha, note: note } });
}
  // MR description edit payloads
for (const iid of Object.keys(mrs)) {
  const mr = mrs[iid];
  if (!mr.gitlabProjectId) continue;
  let desc = mr.description;
  for (const issue of mr.issues) {
    // Replace DEV-NN with [DEV-NN](url), skip if already inside a markdown link
    const re = new RegExp('(?<!\\[)' + issue.key + '\\b(?!\\]\\()', 'g');
    desc = desc.replace(re, `[${issue.key}](${issue.url})`);
  }
  results.push({ json: { linkType: 'mr', gitlabProjectId: mr.gitlabProjectId, mrIid: iid, newDescription: desc } });
}
return results;
